#include <stdio.h>
#include <string.h>
void trim(char *s) {
    int len = strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r')) s[--len] = '\0';
}
int main() {
    char s1[1005], s2[1005];
    if (fgets(s1, sizeof(s1), stdin) && fgets(s2, sizeof(s2), stdin)) {
        trim(s1); trim(s2);
        printf("%s\n", strcmp(s1, s2) == 0 ? "Same" : "Not the same");
    }
    return 0;
}

