using namespace std;
int main() {
    string s1, s2;
    if (getline(cin, s1) && getline(cin, s2)) {
        while (!s1.empty() && (s1.back() == '\r' || s1.back() == '\n')) s1.pop_back();
        while (!s2.empty() && (s2.back() == '\r' || s2.back() == '\n')) s2.pop_back();
        cout << (s1 == s2 ? "Same" : "Not the same") << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s1 = sc.nextLine().replaceAll("[\r\n]", "");
            String s2 = sc.hasNextLine() ? sc.nextLine().replaceAll("[\r\n]", "") : "";
            System.out.println(s1.equals(s2) ? "Same" : "Not the same");
        }
    }
}

